#!/usr/bin/env python3
"""Render static, translated research-domain pages from the saved API snapshot."""
from pathlib import Path
from urllib.parse import urlparse
import html,json,re
ROOT=Path(__file__).resolve().parents[1]
def esc(x):return html.escape(str(x),quote=True)
def safe_url(url):
    assert urlparse(url).scheme=='https',url
    return esc(url)
snapshot=json.loads((ROOT/'data/semantic-scholar-publications.json').read_text())
domains=json.loads((ROOT/'data/research-domains.json').read_text())
editorial=json.loads((ROOT/'data/research-editorial.json').read_text())
translations=json.loads((ROOT/'data/research-translations.json').read_text())
for text in [d['shortDescription'] for d in domains]+[x['summary'] for x in editorial.values()]:
    assert all(translations.get(text,{}).get(lang) for lang in ['es','zh-Hans','hi','ar']),text
for label in [d['label'] for d in domains]+['Recent publications']:
    translations[label+' · BIEEGL']={lang:text+' · BIEEGL' for lang,text in translations[label].items()}
(ROOT/'research-translations.js').write_text('// Generated by scripts/build_research_pages.py.\nObject.assign(window.LAB_TRANSLATIONS, '+json.dumps(translations,ensure_ascii=False,indent=2)+');\n')
index=(ROOT/'index.html').read_text()
header=re.search(r'  <div class="institution-bar">.*?</header>',index,re.S).group()
header=re.sub(r'href="#(.*?)"',r'href="../index.html#\1"',header).replace('src="assets/','src="../assets/')
footer=re.search(r'  <footer>.*?</footer>',index,re.S).group().replace('href="#home"','href="../index.html#home"')
papers={p['id']:p for p in snapshot['papers']}

def paper_card(p):
    # Published titles and source-generated excerpts retain their original language.
    date=p['date'] or str(p['year'] or '')
    preprint='<span class="draft-badge">Preprint · not peer reviewed</span>' if p['preprint'] else ''
    summary=editorial.get(p['id'],{}).get('summary')
    if summary:
        summary_html='<p class="summary-label">Research summary</p><p class="paper-summary" data-localized>'+esc(summary)+'</p>'
    elif p.get('automatedSummary'):
        words=p['automatedSummary'].split();preview=' '.join(words[:24])+('…' if len(words)>24 else '')
        summary_html='<p class="summary-label">Semantic Scholar summary preview (automated)</p><p class="paper-summary" lang="en" dir="ltr" data-original-language>'+esc(preview)+'</p>'
    else:summary_html='<p class="paper-summary">Read the source for details and limitations.</p>'
    return f'''<article class="research-paper" id="paper-{esc(p['id'])}"><p class="publication-meta" lang="en" dir="ltr" data-original-language>{esc(date)} · {esc(p['journal'])}</p>{preprint}<h3 lang="en" dir="ltr" data-original-language><a href="{safe_url(p['url'])}">{esc(p['title'])} <span aria-hidden="true">↗</span></a></h3><p class="paper-contributors"><span>Lab contributors</span>: <span dir="auto">{esc(', '.join(p['labMembers']))}</span></p>{summary_html}<p class="paper-citations"><span>Citation count</span>: {p['citationCount']}</p><div class="paper-source-links"><a href="{safe_url(p['url'])}">Read paper <span aria-hidden="true">↗</span></a><a href="{safe_url(p['semanticScholarUrl'])}">Semantic Scholar record <span aria-hidden="true">↗</span></a></div></article>'''

def area_nav(current):
    links=[(d['id'],d['label']) for d in domains]+[('recent-publications','Recent publications')]
    return '<div class="research-area-nav" role="navigation" aria-label="Research areas">'+''.join(f'<a href="{slug}.html"'+(' aria-current="page"' if slug==current else '')+'>'+esc(label)+'</a>' for slug,label in links)+'</div>'

def render(slug,label,body):
    text=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#052049"><title>{esc(label)} · BIEEGL</title><meta name="description" content="{esc(label)}: example publications from the Brain Imaging and EEG Laboratory."><link rel="icon" href="../assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="../styles.css?v=research-balance"><script src="../translations.js?v=profile-i18n" defer></script><script src="../research-translations.js?v=research-library" defer></script><script src="../script.js?v=anchor-framing" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a>
{header}
<main id="main" class="container research-detail-main"><a class="profile-back" href="../index.html#research">← <span>Back to research</span></a>{area_nav(slug)}{body}<aside class="research-data-note"><p><span>Snapshot date</span>: <time datetime="{snapshot['updated']}">{snapshot['updated']}</time></p><p>Metadata and citation counts come from Semantic Scholar. Coverage is limited to verified author IDs and source-checked lab publications; this is not a complete bibliography. Paper titles and automated summary previews retain their source language.</p><a href="https://www.semanticscholar.org/">Semantic Scholar ↗</a></aside></main>
{footer}
</body></html>'''
    (ROOT/'research'/f'{slug}.html').write_text(text)
(ROOT/'research').mkdir(exist_ok=True)
for d in domains:
    chosen=[papers[id] for id in d['examples'] if id in papers]
    body=f'''<div class="research-domain-intro"><div><p class="eyebrow">Research areas</p><h1>{esc(d['label'])}</h1><p class="lead">{esc(d['description'])}</p></div><img src="../assets/research/{esc(d['image'])}" width="1536" height="1024" alt=""></div><h2>Example publications</h2><p>Selected examples connect our research methods with questions about cognition, psychosis, and mental health.</p><div class="research-paper-list">'''+''.join(paper_card(p) for p in chosen)+'</div>'
    more=[p for p in snapshot['papers'] if d['id'] in p['domains'] and p['recent'] and p['recommendationEligible'] and p['id'] not in d['examples']][:12]
    if more:body+='<details class="more-papers"><summary>More recent papers <span>+</span></summary><div class="research-paper-list">'+''.join(paper_card(p) for p in more)+'</div></details>'
    render(d['id'],d['label'],body)
recommended=[papers[id] for id in snapshot['recentRecommendations']]
body='<p class="eyebrow">Recent publications</p><h1>Recommended reading from the last 12 months</h1><p class="reading-window"><span>Reading window</span>: '+snapshot['windowStart']+' – '+snapshot['windowEnd']+'</p><details class="selection-method"><summary>How these papers are selected <span>+</span></summary><p>Recommendations favor lab involvement and relevance across our research areas, with limited weight for citation signals. Citation counts are not a measure of study quality. Preprints are labeled separately. The featured homepage list remains selected by the lab.</p></details><h2>Recommended reading</h2><div class="research-paper-list">'+''.join(paper_card(p) for p in recommended)+'</div>'
more=[p for p in snapshot['papers'] if p['recent'] and p['recommendationEligible'] and p['id'] not in snapshot['recentRecommendations']]
if more:body+='<details class="more-papers"><summary>More recent papers <span>+</span></summary><div class="research-paper-list">'+''.join(paper_card(p) for p in more)+'</div></details>'
render('recent-publications','Recent publications',body)
print('Generated three domain pages and the last-12-month reading list.')
